#include <bits/stdc++.h>
using namespace std;struct C{int stop,mode,cool,gate,entry,exit;};struct R{double w,dd;int orders;};R run(vector<int>const&p,C c){int cash=10000,sh=0,pend=0,peak=10000,orders=0,tr=0,mr=0,want=0,h=0,lock=0,prior=0;long long ss=0,sl=0,sm=0,sg=0;double dd=0;for(int i=0;i<p.size();i++){int x=p[i],n=0;if(pend==1){n=min(63,max(0,(cash-5)/x));if(n){cash-=n*x+5;sh+=n;orders++;}}else if(pend==2){n=min(63,sh);if(n&&cash+n*x>=5){cash+=n*x-5;sh-=n;orders++;}}int w=cash+sh*x;peak=max(peak,w);dd=max(dd,double(peak-w)/peak);ss+=x-(i>=20?p[i-20]:0);sl+=x-(i>=120?p[i-120]:0);sm+=x-(i>=60?p[i-60]:0);sg+=x-(i>=c.gate?p[i-c.gate]:0);if(i+1>=120){int d=ss*120-sl*20,dm=x*60-sm;if(d>c.entry*2400)tr=1;else if(d<-c.exit*2400)tr=0;if(dm<-240)mr=1;else if(dm>0)mr=0;want=tr||(mr&&d>=-9600);if(c.mode==1&&i>=c.gate&&x*c.gate<sg-c.stop*c.gate)want=0;else if(c.mode==2&&i>=c.gate&&ss*c.gate<sg*20-c.stop*c.gate*20)want=0;else if(c.mode>=3){if(lock>0)lock--;if(prior){h=max(h,x);if((c.mode==3? h-x>=c.stop:(h-x)*100>=c.stop*h)){lock=c.cool;tr=mr=0;want=0;}}if(lock)want=0;if(want&&!prior)h=x;prior=want;}}pend=want?1:2;}return{double(cash+sh*p.back()),dd,orders};}
vector<int>read(string f){ifstream in(f);string s;getline(in,s);vector<int>p;while(getline(in,s))if(s.size())p.push_back(stoi(s.substr(s.find(',')+1)));return p;}
int main(){auto a=read("tb/practica.csv"),b=read("tb/practica_meta.csv");vector<vector<int>> tr;for(auto p:{a,b})for(int i=0;i<12000;i+=3000)tr.emplace_back(p.begin()+i,p.begin()+i+3000);vector<C> cs;cs.push_back({0,0,0,120,8,8});for(int entry:{2,4,6,8,10})for(int exit:{0,2,4,6,8}){cs.push_back({0,0,0,120,entry,exit});for(int g:{120,256,512,1024})for(int stop:{0,2,4,6,8,12,16})for(int mode:{1,2})cs.push_back({stop,mode,0,g,entry,exit});for(int stop:{3,4,5,6,8,10,12,16})for(int cool:{16,32,64,120,240})for(int mode:{3,4})cs.push_back({stop,mode,cool,120,entry,exit});}vector<pair<double,int>> rs;for(int k=0;k<cs.size();k++){double s[2]={};for(int i=0;i<8;i++){auto r=run(tr[i],cs[k]);s[i/4]+=(log(max(1.,r.w)/10000.)-.5*r.dd)/4;}rs.push_back({(s[0]+s[1])/2-.6*abs(s[0]-s[1]),k});}sort(rs.rbegin(),rs.rend());auto show=[&](C c,double sc){cout<<sc<<" "<<c.stop<<" "<<c.mode<<" "<<c.cool<<" "<<c.gate<<" "<<c.entry<<" "<<c.exit;for(auto p:{a,b}){auto r=run(p,c);vector<int>h(p.begin()+12000,p.end());auto t=run(h,c);cout<<" full "<<r.w<<" "<<r.dd<<" test "<<t.w<<" "<<t.dd;}cout<<"\n";};show(cs[0],0);for(int i=0;i<20;i++)show(cs[rs[i].second],rs[i].first);}
